//! Sorting of small arrays of integer keys (the encoded float keys).
//!
//! Up to 32 keys: a sorting network of exactly the array's length (pruned
//! Batcher networks, `small_networks.rs`, generated by
//! `tools/gen_networks.py`). Each compare-exchange is a `min` / `max` pair,
//! compiled to conditional selects: no data-dependent branch. From 5 keys a
//! branch-free order probe first returns ascending input as is and reverses
//! descending input.

use std::convert::TryFrom;

include!("small_networks.rs");

/// Largest length sorted by a network.
pub(crate) const NETWORK_MAX: usize = 32;
/// From this length the order probe runs before the network (shorter
/// networks cost about as much as the probe).
const PROBE_MIN: usize = 5;

#[inline(always)]
fn cswap<K: Copy + Ord, const N: usize>(a: &mut [K; N], i: usize, j: usize) {
    let (x, y) = (a[i], a[j]);
    a[i] = x.min(y);
    a[j] = x.max(y);
}

/// Sorts at most `NETWORK_MAX` raw keys in place: `encode` maps them to keys
/// whose unsigned order is the wanted order, `decode` maps them back.
#[inline]
pub(crate) fn network_sort<K: Copy + Ord>(keys: &mut [K], encode: impl Fn(K) -> K, decode: impl Fn(K) -> K) {
    let n = keys.len();
    debug_assert!(n <= NETWORK_MAX);
    if n < 2 {
        return;
    }
    keys.iter_mut().for_each(|k| *k = encode(*k));
    let mut sorted = false;
    if n >= PROBE_MIN {
        let (mut asc, mut desc) = (true, true);
        for w in keys.windows(2) {
            asc &= w[0] <= w[1];
            desc &= w[0] >= w[1];
        }
        if desc && !asc {
            keys.reverse();
        }
        sorted = asc || desc;
    }
    if !sorted {
        network_any(keys);
    }
    keys.iter_mut().for_each(|k| *k = decode(*k));
}
